#!/usr/bin/env python3
"""Génère les pages lisibles sans JS depuis les contenus séparés des enquêtes."""
from pathlib import Path
from html import escape as e
import json,argparse,sys,re
R=Path(__file__).resolve().parents[1]
VERDICTS={'etayee':'Affirmation étayée','limitee':'Portée limitée','contredite':'Affirmation contredite','insuffisante':'Informations insuffisantes'}
def shell(name,title,desc,body,script=''):
 url='https://thot-culture.github.io/Thot/enquetes/'+name
 schema=json.dumps({'@context':'https://schema.org','@type':'CollectionPage' if name=='index.html' else 'LearningResource','name':title,'description':desc,'url':url,'inLanguage':'fr','publisher':{'@type':'Organization','name':'THOT'}},ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{e(title,quote=True)} — THOT"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:image" content="https://thot-culture.github.io/Thot/{('assets/og-thot.png' if name=='index.html' else 'assets/explorer/partage-enquete-'+name.removesuffix('.html')+'.png')}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Carte typographique THOT : {e(title,quote=True)}"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{url}"><title>{e(title)} — Les enquêtes THOT</title><script type="application/ld+json">{schema}</script><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/notre-methode.css"><link rel="stylesheet" href="../assets/enquetes/enquetes.css?v=1"></head>
<body><a class="skip-link" href="#contenu">Aller au contenu</a><header class="top"><div class="wrap nav"><a class="brand" href="../index.html" aria-label="THOT, accueil">THOT</a><nav class="nav-links" aria-label="Navigation principale"><a href="../bibliotheque.html">Bibliothèque</a><a href="../explorer.html">Explorer</a><a href="index.html" aria-current="{'page' if name=='index.html' else 'true'}">Les enquêtes THOT</a><a href="../quiz.html#quiz-classique">Quiz</a></nav></div></header><main id="contenu" class="wrap" tabindex="-1">{body}</main><footer><div class="wrap foot"><b>THOT · La curiosité en pratique</b><nav aria-label="Poursuivre l’exploration"><a href="index.html">Toutes les enquêtes</a><a href="../notre-methode.html">Notre méthode</a></nav></div></footer>{script}</body></html>\n'''
def graph(id,title):
 return f'''<figure class="chart-figure"><figcaption>{title}</figcaption><svg id="{id}" viewBox="0 0 340 245" role="img" aria-labelledby="{id}-titre {id}-desc"><title id="{id}-titre">Prix fictifs : 8 puis 10 euros</title><desc id="{id}-desc">Axe vertical de 0 à 12 euros. Prix de 8 euros au jour 1 et de 10 euros au jour 30.</desc><text x="12" y="18">Prix (€)</text><g data-ticks></g><line x1="55" x2="310" y1="200" y2="200" stroke="#17243a"/><line x1="55" x2="55" y1="35" y2="200" stroke="#17243a"/><rect data-bar="8" x="95" y="90" width="60" height="110" fill="#245d63"/><rect data-bar="10" x="220" y="62.5" width="60" height="137.5" fill="#927038"/><text data-value="8" x="125" y="82" text-anchor="middle">8 €</text><text data-value="10" x="250" y="54.5" text-anchor="middle">10 €</text><text x="125" y="225" text-anchor="middle">Jour 1</text><text x="250" y="225" text-anchor="middle">Jour 30</text><text data-bottom x="55" y="241">Départ : 0 € · maximum : 12 €</text><g class="static-ticks"><text x="42" y="204" text-anchor="end">0</text><text x="42" y="149" text-anchor="end">4</text><text x="42" y="94" text-anchor="end">8</text><text x="42" y="39" text-anchor="end">12</text></g></svg></figure>'''
def visual(d):
 if d['kind']=='survey':return '<p class="mission">Votre outil : ouvrez les questions du dossier, dans l’ordre qui vous paraît utile. Lire une pièce et la retenir comme preuve sont deux actions différentes.</p>'
 if d['kind']=='chart':return '''<section class="atelier" aria-labelledby="atelier-titre"><h2 id="atelier-titre">Changez l’échelle, gardez les données</h2><div class="chart-controls" data-interactive hidden><label for="depart">Départ de l’axe vertical du graphique réglable</label><input type="range" id="depart" min="0" max="7" value="0" step="1"><output id="depart-valeur" for="depart" aria-live="polite">0 €</output><button type="button" data-zero>Revenir à un départ de zéro</button></div><div class="charts">'''+graph('graph-reglable','Vue réglable · mêmes prix, départ choisi')+graph('graph-zero','Référence fixe · axe partant de zéro')+'''</div><p>Unités : euros. Dates fictives : jours 1 et 30. Valeurs : <strong>8 € et 10 €</strong>. Aucun prix intermédiaire n’est connu.</p></section>'''
 return '''<section class="atelier" aria-labelledby="photo-titre"><h2 id="photo-titre">Examinez avant d’interpréter</h2><p id="photo-mode">Image entière. Avec les commandes, vous pourrez isoler une fenêtre d’affichage sans modifier le fichier.</p><div class="photo-controls" data-interactive hidden><button type="button" data-photo="full" aria-pressed="true" aria-controls="photo-cadre">Afficher l’image entière</button><button type="button" data-photo="crop" aria-pressed="false" aria-controls="photo-cadre">Examiner un cadrage partiel</button></div><figure><div class="photo-frame" id="photo-cadre"><img id="photo-original" src="../assets/enquetes/apollo08-earthrise-original.jpg" alt="La Terre sur un fond sombre, au-dessus d’un horizon lunaire gris au premier plan. Ces pixels ne situent pas précisément le photographe." width="1041" height="1000" decoding="async"></div><figcaption>Photographie réelle « Earthrise » · NASA / Bill Anders · Apollo 8. Fichier fourni par la NASA, intact. Le cadrage d’affichage est un ajout réversible de THOT.</figcaption></figure><p id="photo-erreur" role="status" hidden>L’image n’a pas pu être chargée. La description et la notice restent disponibles ; elles ne remplacent pas l’observation de l’image. <button type="button" data-retry>Réessayer de charger l’image</button></p><p class="provenance"><a href="../assets/enquetes/apollo08-earthrise-original.jpg">Ouvrir le fichier complet intact</a> · <a href="https://www.nasa.gov/image-article/apollo-8-earthrise/" target="_blank" rel="noopener noreferrer">Notice NASA et contexte</a> · <a href="https://www.nasa.gov/nasa-brand-center/images-and-media/" target="_blank" rel="noopener noreferrer">Conditions NASA de réutilisation</a>. Usage pédagogique avec attribution selon ces conditions ; aucune caution de la NASA à l’exercice n’est revendiquée.</p></section>'''
def dossier(d):
 pieces=''.join(f'<details class="piece" id="piece-{p["id"]}"><summary>{e(p["title"])}</summary><p>{e(p["body"])}</p><p class="piece-action" data-interactive hidden><a href="#carnet">Retenir une preuve dans le carnet</a></p></details>' for p in d['pieces'])
 boxes=''.join(f'<label class="proof-option"><input type="checkbox" value="{p["id"]}" data-proof> <span>{e(p["proof"])}</span></label>' for p in d['pieces'])
 hints=''.join(f'<details class="hint"><summary>Indice facultatif {i+1}</summary><p>{e(t)}</p></details>' for i,t in enumerate(d['hints']))
 options=''.join(f'<option value="{k}">{v}</option>' for k,v in VERDICTS.items())
 body=f'''<a class="back" href="index.html">← Toutes les enquêtes</a><header class="case-header"><p class="eyebrow">Dossier · {e(d['tag'])}</p><h1>{e(d['title'])}</h1><p class="fiction">{e(d['notice'])}</p><p class="time">Environ 3 à 5 minutes · indices facultatifs · sans score</p><p>{e(d['intro'])}</p></header><section class="claim" aria-labelledby="affirmation"><h2 id="affirmation">L’affirmation à examiner</h2><blockquote>{e(d['claim'])}</blockquote>{'<p>Légende créée pour cet exercice, et non tirée d’une publication réelle.</p>' if d['kind']=='photo' else ''}</section><div data-dossier="{d['slug']}">{visual(d)}<section class="pieces" aria-labelledby="pieces-titre"><h2 id="pieces-titre">Ouvrez le dossier</h2><p>Les pièces se consultent librement. Vous pouvez ensuite retenir celles qui vous semblent utiles, sans obligation de tout cocher.</p>{pieces}</section><section class="carnet" id="carnet" aria-labelledby="carnet-titre"><h2 id="carnet-titre">Votre carnet de preuves</h2><p>Retenez une observation que vous savez expliquer. Une pièce consultée n’est pas automatiquement comprise.</p><div data-interactive hidden><fieldset><legend>Les éléments que je retiens</legend>{boxes}</fieldset><p class="notebook-count" role="status" aria-live="polite" data-notebook>Aucune preuve retenue.</p></div><noscript><p>Sans JavaScript, notez les lettres des pièces qui étayent votre avis, puis comparez avec l’explication en bas de page.</p></noscript></section><section class="hints" aria-labelledby="hints-titre"><h2 id="hints-titre">Un coup de pouce ?</h2><p>Demander un indice ne retire rien à votre enquête.</p>{hints}</section><form class="conclusion" data-interactive hidden><h2>Votre conclusion, pour le moment</h2><label for="avis">Au vu des pièces, je considère l’affirmation…</label><select id="avis" name="avis"><option value="">Choisir une conclusion</option>{options}</select><label for="raison">Pourquoi ? Reliez votre avis à une ou plusieurs pièces.</label><textarea id="raison" name="raison" rows="3" maxlength="600" required placeholder="Je retiens la pièce… parce que…"></textarea><p>Votre phrase reste dans cette page : aucun envoi, compte ou sauvegarde automatique.</p><button class="primary-action" type="submit">Confronter ma conclusion aux pièces</button><button type="button" data-reset>Recommencer cette enquête</button></form><p class="case-status" role="status" aria-live="polite" aria-atomic="true" data-status></p><section class="resolution" tabindex="-1" aria-labelledby="resolution-titre" hidden><h2 id="resolution-titre">Le dénouement expliqué</h2><div data-result></div><button type="button" data-revise>Réviser ma conclusion</button></section><details class="text-solution"><summary>Lire l’explication sans jouer</summary><p>{e(d['answer'])}</p><p>{e(d['limits'])}</p><p><strong>À vérifier ensuite :</strong> {e(d['next'])}</p><p><strong>Le réflexe :</strong> {e(d['reflex'])}</p></details></div>'''
 data=json.dumps(d,ensure_ascii=False).replace('</','<\\/')
 return shell(d['slug']+'.html',d['title'],d['intro'],body,f'<script type="application/json" id="dossier-donnees">{data}</script><script src="../assets/enquetes/enquetes.js?v=1" defer></script>')
def outputs():
 data=json.loads((R/'assets/enquetes/dossiers.json').read_text())
 slugs=set()
 for d in data:
  assert re.fullmatch('[a-z][a-z0-9-]*',d['slug']) and d['slug'] not in slugs, 'Slug invalide ou dupliqué'
  slugs.add(d['slug'])
  assert d['kind'] in {'survey','chart','photo'}, 'Type de manipulation à implémenter explicitement'
  assert d['expected'] in VERDICTS
  ids=[p['id'] for p in d['pieces']]
  assert len(ids)==len(set(ids)) and all(re.fullmatch('[a-z][a-z0-9-]*',id) for id in ids), 'Identifiants de pièces'
  assert set(d['required'])<=set(ids) and d['supports'] and all(group and set(group)<=set(ids) for group in d['supports']), 'Appuis inconnus'
  assert all(d[key].strip() for key in ['title','notice','claim','intro','answer','limits','next','reflex'])
  assert d['hints'] and all(h.strip() for h in d['hints'])
  assert all(all(p[key].strip() for key in ['title','body','proof','feedback']) for p in d['pieces'])
 cards=''.join(f'<article class="investigation-card"><p class="eyebrow">Dossier {i+1} · {e(d["tag"])}</p><h2><a href="{d["slug"]}.html">{e(d["title"])}</a></h2><p>{e(d["intro"])}</p><p class="case-note">{e(d["notice"])}</p><a class="start" href="{d["slug"]}.html">Ouvrir l’enquête <span class="sr-only">{e(d["title"])}</span> →</a><p class="time">3 à 5 minutes environ</p></article>' for i,d in enumerate(data))
 body='<header class="case-header"><p class="eyebrow">Examiner · comparer · justifier</p><h1>Les enquêtes THOT</h1><p class="lead">Trois petits dossiers pour ajuster son avis aux preuves.</p><p>Ouvrez les pièces, manipulez ce qui peut l’être, retenez les preuves utiles et expliquez votre conclusion. Le dénouement vous aide à la réviser : pas de profil, de classement ou de score d’esprit critique.</p><p>Sans compte et sans sauvegarde automatique. Les indices sont facultatifs et ne coûtent rien. Une affirmation peut être étayée, limitée, contredite ou encore indécidable.</p></header><div class="investigation-grid">'+cards+'</div><p class="example">Le bon réflexe n’est pas de douter de tout : c’est de chercher ce que les informations permettent réellement de conclure.</p>'
 return {R/'enquetes/index.html':shell('index.html','Les enquêtes THOT','Trois enquêtes pour examiner les preuves, les graphiques et le contexte des images.',body),**{R/f'enquetes/{d["slug"]}.html':dossier(d) for d in data}}
if __name__=='__main__':
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--check',action='store_true');args=ap.parse_args();bad=[]
 for p,s in outputs().items():
  if args.check:
   if not p.exists() or p.read_text()!=s:bad.append(str(p.relative_to(R)))
  else:p.write_text(s)
 if bad:sys.exit('Pages à générer : '+', '.join(bad))
 print('PASS : quatre pages cohérentes avec les contenus séparés.' if args.check else 'Quatre pages générées.')
